-- Function: public.fn_get_due_material_recurring_schedules
-- Backup generated on 2026-10-25 20:33:15

CREATE OR REPLACE FUNCTION public.fn_get_due_material_recurring_schedules(p_as_of_date timestamp with time zone)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, classroom_id uuid, schedule_type character varying, frequency character varying, material_product_id uuid, offering_id uuid, quantity integer, loan_duration_days integer, delivery_address text, next_run_date timestamp with time zone, last_run_date timestamp with time zone, status character varying, notes text, created_by_user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone, product_name character varying, product_sku character varying)  LANGUAGE sql  STABLE AS $function$     SELECT          s.id, s.tenant_id, s.organization_id, s.branch_id, s.classroom_id, s.schedule_type,         s.frequency, s.material_product_id, s.offering_id, s.quantity, s.loan_duration_days,         s.delivery_address, s.next_run_date, s.last_run_date, s.status, s.notes,         s.created_by_user_id, s.created_at, s.updated_at,         p.name AS product_name, p.sku AS product_sku     FROM material_recurring_schedules s     JOIN material_products p ON s.material_product_id = p.id     WHERE s.status = 'Active' AND s.next_run_date <= p_as_of_date     ORDER BY s.next_run_date ASC; $function$ ;
